// Parliamentary Procedure Practice Test 4. Original questions written for Valus from the HOSA 2026–27
// test plan (National Association of Parliamentarians topics), slightly harder than the sample items:
// applying Robert’s Rules to meeting situations, vote thresholds and motion characteristics.
import {q, mix} from './q.js';
const RONR='Robert’s Rules of Order Newly Revised', BRIEF='Robert’s Rules of Order Newly Revised In Brief';
const WHY='Why Have Rules', MEET='What Happens at a Meeting?', MOT='Handling Motions', DEB='Debate', AMD='Amendments', POST='Postponing and Referring to a Committee', MIND='How a Group Can Change Its Mind', VOTE='Voting and Elections', BYL='Bylaws and Other Rules and How to Use Them', ENF='How Rules are Enforced and Suspended', TABLE='Table of Rules', OFF='Officers, Committee Chairman, or Member';

export default {
 id:'parliamentary-procedure-4',
 event:'Parliamentary Procedure',
 title:'Practice Test 4',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Robert’s Rules of Order Newly Revised, RONR In Brief and NAP study questions',
 plan:[{area:'National Association of Parliamentarians',weight:100,topics:[WHY,MEET,MOT,DEB,AMD,POST,MIND,VOTE,BYL,ENF,TABLE,OFF]}],
 questions:mix([
  q(WHY,'Which members must receive notice of a regular or special meeting?','All members of the assembly',['Only the officers and board members','Only members who attended last time','Only members who asked for a notice'],'A','Every member has the right to notice of meetings; a special meeting held without proper notice to all members cannot validly transact business.',RONR),
  q(WHY,'Unless the bylaws say otherwise, what is the quorum of a convention of delegates?','A majority of the delegates registered as attending',['A majority of all delegates who could be elected','Any number of delegates who are present that day','Two-thirds of the chartered units represented'],'B','In a convention, the quorum is a majority of the delegates who have registered as attending, even if some later leave, unless the bylaws set another number.',RONR),
  q(WHY,'A motion would give a contract to a member’s own business. What should that member do about voting?','Abstain, since they have a direct personal interest',['Vote first so that others can follow their lead','Vote twice, once as a member and once as owner','Ask the chair to cast their vote for them'],'C','A member should not vote on a question in which they have a direct personal or financial interest not shared by other members, though RONR cannot compel the abstention.',RONR),
  q(WHY,'How do previous-notice requirements protect members who are absent from a meeting?','They warn members that important changes will be considered',['They let absent members vote by proxy at the meeting','They allow absent members to veto actions afterward','They require every vote to be unanimous among those present'],'D','Requiring notice for actions such as rescinding or amending bylaws protects absentees, who can attend if they care about the change.',RONR),
  q(MEET,'All business on the agenda is finished, and no one seeks the floor. How may the chair close the meeting?','Declare it adjourned by general consent',['Wait until a motion to recess is made','Ask the secretary to end the meeting','Leave without saying anything formal'],'A','When the agenda is complete and no member seeks the floor, the chair may ask if there is further business and then declare the meeting adjourned.',RONR),
  q(MEET,'The treasurer’s report has been audited. Which report does the assembly vote to adopt?','The auditors’ report',['The treasurer’s report itself','The secretary’s minutes of the audit','The president’s annual message'],'B','A treasurer’s report is simply received, but the auditors’ report is adopted, which relieves the treasurer of responsibility for the period covered.',RONR),
  q(MEET,'In the standard order of business, which reports follow the reports of standing committees?','Reports of special committees',['Reports of officers and boards','Reading of the minutes','Announcements of new members'],'C','The standard order lists reports of officers, boards and standing committees, then reports of special (select or ad hoc) committees, then special orders.',RONR),
  q(MEET,'An error is found in minutes that were approved months ago. How can they be corrected?','By the motion to amend something previously adopted',['By the secretary editing them without a vote','By a point of order, decided by the chair alone','They can never be corrected once approved'],'D','Approved minutes can be corrected later through the motion to amend something previously adopted, regardless of how long ago they were approved.',RONR),
  q(MOT,'Before the chair has stated a motion, can its maker withdraw it?','Yes, freely and without permission',['No, it already belongs to the assembly','Only by a two-thirds vote of members','Only if the seconder also withdraws'],'A','Until the chair states the question, the motion belongs to its maker, who may withdraw or modify it without anyone’s consent.',RONR),
  q(MOT,'Must a member be recognized by the chair before seconding a motion?','No; a member may second without obtaining the floor',['Yes; the member must rise and be recognized first','Yes; and the second must be put in writing','No; but only officers may second a motion'],'B','Seconding is done without obtaining the floor; a member simply calls out “Second!” or “I second the motion.”',RONR),
  q(MOT,'A member offers a long, complicated motion aloud. What may the chair do?','Ask the member to put the motion in writing',['Rule it out of order because of its length','Shorten it on the chair’s own authority first','Refer it to the parliamentarian for a ruling'],'C','The chair may require that a long or complicated main motion or amendment be put in writing so it is stated accurately.',RONR),
  q(MOT,'What do incidental motions have in common?','They deal with questions of procedure arising from business',['They introduce new business to the assembly for a vote','They are urgent matters unrelated to any pending business','They bring back questions that were decided earlier'],'D','Incidental motions, such as point of order and division of the assembly, deal with procedure arising out of pending business or another motion.',RONR),
  q(DEB,'A member finishes speaking early and offers their remaining time to another member. Is this allowed?','No; a member cannot yield remaining time to another',['Yes; any member may yield their time to a friend','Yes; but only to a member who is on the same side','No; unless the other member is an officer of the group'],'A','Under RONR, unused time in a speech is simply lost; members cannot transfer it, which protects equal rights in debate.',RONR),
  q(DEB,'An amendment is pending. What may members discuss in debate?','The amendment only, not the whole main motion',['Any part of the main motion they choose','Any new topic, once they hold the floor','Only the procedure for voting on it'],'B','Debate on an amendment is limited to the amendment, though members may touch on the main motion only as needed to explain their view on it.',RONR),
  q(DEB,'A member moves “the previous question” without saying on what. Which question does it apply to?','Only the immediately pending question',['Every motion pending before the assembly','Only the original main motion itself','The question pending the longest time'],'C','Unless qualified, the previous question applies only to the immediately pending question; a member may specify it to apply to all pending questions.',RONR),
  q(DEB,'A member has already spoken twice on a motion today and wants to speak a third time. What is required?','A two-thirds vote, or general consent, to extend debate',['Nothing; members may speak as often as they like','The permission of the member who made the motion','A majority vote to reconsider the motion first'],'D','Each member may speak twice per day on a debatable question; speaking more needs the limits of debate extended by two-thirds or general consent.',RONR),
  q(AMD,'Which of these motions cannot be amended?','Adjourn, when it is privileged',['Commit or refer','Postpone to a certain time','A main motion'],'A','The privileged motion to adjourn is not amendable; commit, postpone to a certain time and main motions all may be amended.',RONR),
  q(AMD,'A member moves to “add” words to a motion. Where do the words go?','At the end of the motion',['At the start of the motion','In place of the last sentence','Anywhere the chair chooses'],'B','“Add” places new words at the end of a motion or paragraph; “insert” places them before or between existing words.',RONR),
  q(AMD,'To be in order, a secondary amendment must be germane to what?','The primary amendment it proposes to change',['The main motion’s purpose, even if unrelated','The organization’s mission or vision only','The previous meeting’s minutes and records'],'C','A secondary amendment amends the primary amendment, so it must relate directly to the primary amendment’s subject.',RONR),
  q(AMD,'An amendment is adopted, but the main motion as amended is then defeated. What has the assembly adopted?','Nothing; the amendment falls with the main motion',['The amendment only, as a separate standing rule','The main motion in its original wording','The amendment and the main motion together'],'D','An amendment only changes a pending motion; if the main motion is lost, nothing is adopted, including the amendment.',BRIEF),
  q(POST,'A motion is referred to a committee “with instructions to report by March 1.” What is the committee’s duty?','To follow the instructions given by the assembly',['To ignore them if the committee chair disagrees','To report whenever the committee is ready','To return the motion without any study'],'A','A motion to commit may include instructions, and the committee is bound to carry them out, including deadlines for reporting.',RONR),
  q(POST,'What is a committee of the whole?','The entire assembly acting as a committee with freer debate',['A committee that includes every officer but no members','A standing committee of past presidents of the group','A committee named only for elections and ballots'],'B','In a committee of the whole, the full assembly acts as a committee, often with more informal debate, and then reports to itself as the assembly.',RONR),
  q(POST,'Which subsidiary motion ranks lowest?','Postpone indefinitely',['Commit or refer','Amend','Lay on the table, when urgent'],'C','Subsidiary motions rank from lay on the table (highest) down through previous question, limit debate, postpone to a certain time, commit and amend to postpone indefinitely (lowest).',RONR),
  q(POST,'A motion was postponed to the next meeting as a general order, but time ran out before it was reached. What happens?','It becomes unfinished business at the following meeting',['It is automatically adopted by default at adjournment','It is permanently dropped and cannot return to the floor','It becomes a special order by majority vote'],'D','A general order not reached when the meeting adjourns carries over as unfinished business to the next regular meeting.',RONR),
  q(MIND,'What is the purpose of the motion to “reconsider and enter on the minutes”?','To prevent a temporary majority from taking unfair action',['To cancel a motion adopted at an earlier session','To approve minutes from the previous meeting','To ask the secretary to read a motion aloud'],'A','Reconsider and enter on the minutes delays reconsideration to a later meeting, protecting against an unrepresentative majority in a poorly attended meeting.',RONR),
  q(MIND,'A motion was adopted 10 minutes ago, and reconsider could still be moved. Is a motion to rescind in order?','No; reconsider must be used while it is still available',['Yes; rescind is always in order instead of reconsider','Yes; but only by unanimous consent of those present','No; adopted motions cannot be changed in any way'],'B','Rescind is not in order while the question can still be reached by a motion to reconsider that has already been or could be made.',RONR),
  q(MIND,'Only a member on the prevailing side may move to reconsider. Who may second it?','Any member, regardless of how they voted',['Only a member on the losing side','Only a member who also voted yes','Only the member who made the original motion'],'C','The maker of the motion to reconsider must have voted with the prevailing side, but any member may second it.',RONR),
  q(MIND,'Rescind, reconsider, take from the table and discharge a committee belong to which group?','Motions that bring a question again before the assembly',['Privileged motions that rank above all others','Subsidiary motions that dispose of a main motion','Incidental motions that settle points of order'],'D','RONR groups take from the table, rescind or amend something previously adopted, discharge a committee and reconsider as motions that bring a question again before the assembly.',RONR),
  q(VOTE,'In an officer election, 100 ballots are cast: 48 for Lee, 40 for Kim, 8 illegal ballots from legal voters and 4 blanks. What is the result?','No one is elected, because 49 votes were needed',['Lee is elected with a majority of legal votes','Lee is elected because 48 is the most votes','Kim is elected after the illegal ballots are removed'],'A','Blanks are ignored, but illegal ballots from legal voters count toward votes cast, so 96 votes were cast and a majority is 49; Lee’s 48 is short.',RONR),
  q(VOTE,'An organization has 80 members, and a vote requires a majority of the entire membership. How many yes votes are needed?','41',['40','31','54'],'B','A majority of the entire membership is more than half of all 80 members, or 41 votes, no matter how many attend.',RONR),
  q(VOTE,'Only one candidate is nominated for an office, and the bylaws do not require a ballot. How may the chair proceed?','Declare the candidate elected by acclamation',['Postpone the election until a second nominee','Hold a ballot vote anyway, as RONR requires','Ask the candidate to withdraw and reopen nominations'],'C','When there is only one nominee and the bylaws do not require a ballot, the chair may declare that candidate elected, which is election by acclamation.',RONR),
  q(VOTE,'During a rising vote, may a member change their vote?','Yes, until the result is announced',['No, once they have stood up','Only with the chair’s permission','Only by a motion to reconsider'],'D','A member may change their vote up until the chair announces the result; after that, it takes general consent.',RONR),
  q(VOTE,'An organization wants members to vote by mail on a bylaw amendment. When is this allowed?','Only when the bylaws authorize mail voting',['Always, because RONR favors mail ballots','Whenever the president approves it','Only when a quorum cannot be reached'],'A','Because RONR assumes members vote in person at a meeting, voting by mail or electronically is valid only when the bylaws authorize it.',RONR),
  q(BYL,'Unless otherwise stated, when does a bylaw amendment take effect?','Immediately upon its adoption',['At the start of the next fiscal year','After the next annual meeting','Once the president signs it'],'B','A bylaw amendment takes effect as soon as it is adopted unless the motion or a proviso sets a later time.',RONR),
  q(BYL,'How does a revision of the bylaws differ from an ordinary amendment?','The entire document is opened to change as a whole new set',['Only one article may be changed at each meeting','It needs no previous notice to the members','It can be adopted by the board alone without members'],'C','A revision substitutes an entirely new set of bylaws, so the whole document is open to amendment, unlike an amendment limited to the scope of the notice.',RONR),
  q(BYL,'A bylaw is unclear, and members disagree on its meaning. Who has the authority to interpret it?','The organization itself, through its assembly',['A court, before any vote can be taken','The national parliamentarians’ association','The member who first wrote that bylaw'],'D','Each society decides for itself the meaning of its bylaws; the chair may rule, subject to appeal, and RONR gives principles of interpretation.',RONR),
  q(BYL,'Where are the powers of an organization’s executive board defined?','In the bylaws',['In the minutes','In the agenda','In the budget'],'A','An executive board has only the powers delegated to it by the bylaws; it cannot change actions of the full assembly unless the bylaws allow.',RONR),
  q(ENF,'The chair rules that a point of order is “well taken.” What does this mean?','The chair agrees that a rule was broken',['The point is rejected as unfounded','The point is sent to the assembly','The member who raised it must apologize'],'B','“Well taken” means the chair sustains the point of order and corrects the error; “not well taken” means the chair rejects it.',RONR),
  q(ENF,'Before a member is expelled, what basic protection does RONR require?','Notice of the charges and a fair hearing',['A second and a majority voice vote','Approval by the parliamentarian alone','A ruling by the chair without debate'],'C','Disciplining a member requires due process: formal notice of the charges and a chance to be heard before the assembly decides.',RONR),
  q(ENF,'A member appeals the chair’s ruling about indecorum in debate. Is the appeal debatable?','No; appeals about indecorum are not debatable',['Yes; every appeal is fully debatable','Yes; but only by the chair and the appellant','No; appeals are not allowed on such rulings'],'D','An appeal is usually debatable, but not when it relates to indecorum, speaking rules or priority of business, or when an undebatable question is pending.',RONR),
  q(ENF,'A member begins speaking without being recognized by the chair. What should the chair do?','Call the member to order',['Let them continue, to save time','Ask the assembly to vote on it','Recess the meeting immediately'],'A','Members must obtain the floor before speaking; the chair should call to order a member who speaks without being recognized.',RONR),
  q(TABLE,'A member moves to recess when no business is pending. How is the motion treated?','As a main motion, which is debatable',['As a privileged motion, undebatable','As an incidental motion, no second','As out of order until business arises'],'B','Recess is privileged only when other business is pending; made when nothing is pending, it is a main motion and is debatable and amendable.',RONR),
  q(TABLE,'What does a call for the orders of the day require?','No second and no vote; one member may demand it',['A second and a majority vote to adopt it','A two-thirds vote to enforce the adopted agenda','The approval of the program committee’s chair'],'C','A single member may call for the orders of the day; the chair must then follow the agenda unless the assembly sets it aside by a two-thirds vote.',RONR),
  q(TABLE,'What vote does a motion for division of the question require?','A majority vote',['A two-thirds vote','No vote at all','A unanimous vote'],'D','Division of the question is an incidental motion that needs a second and a majority vote, unless the parts are separate resolutions, which must be divided on request.',RONR),
  q(TABLE,'When is a motion to reconsider debatable?','When the motion being reconsidered is debatable',['Never; reconsider is always undebatable','Always; reconsider is always debatable','Only when the original motion needed two-thirds'],'A','Reconsider takes on the debatability of the motion it would reconsider; if that motion is debatable, so is reconsider, and its debate opens the merits.',RONR),
  q(TABLE,'Is the motion to suspend the rules debatable?','No, and it requires a two-thirds vote',['Yes, and it requires a majority vote','Yes, and it requires a two-thirds vote','No, and it requires a majority vote'],'B','Suspend the rules is not debatable or amendable and usually requires a two-thirds vote, because it sets aside rules that protect members.',RONR),
  q(OFF,'If the organization’s rules do not say otherwise, who appoints the parliamentarian?','The president',['The secretary','The full membership','The treasurer'],'C','The parliamentarian is a consultant to the presiding officer, so the president usually appoints them unless the rules provide another method.',RONR),
  q(OFF,'Why do bylaws often say officers serve “for one year or until their successors are elected”?','To prevent a vacancy if an election is delayed',['To let officers stay in office for life','To allow officers to choose their successors','To avoid holding any elections at all'],'D','The phrase “or until their successors are elected” keeps officers in place if an election is delayed, so offices are not left empty.',RONR),
  q(OFF,'An office becomes vacant, and the bylaws do not say how to fill it. Who fills it?','The body that elected the officer, after notice',['The officer who left, by naming a successor','The parliamentarian, by appointing someone','No one; it stays empty until the next term'],'A','Unless the bylaws provide otherwise, the body that elects officers fills vacancies, and notice of the election must be given to members.',RONR),
  q(OFF,'Where do an officer’s duties come from?','The bylaws and the parliamentary authority',['The officer’s personal preferences','The outgoing officer’s private notes','Any member who asks for a task'],'B','An officer’s duties are those listed in the bylaws, plus those the parliamentary authority assigns, such as the secretary keeping minutes.',RONR)
 ],8943)
};
